```typescript
import type {
  Provider,
  CodespacesConfig,
  DeployOptions,
  Deployment,
  DeploymentStatus,
  DeploymentUrls,
  ListFilters
} from '../../types.js';
import {
  AuthenticationError,
  DeploymentFailedError,
  ProviderError
} from '../../core/errors.js';
import {
  checkGhCliInstalled,
  checkGhAuthenticated,
  createCodespace,
  waitForCodespaceReady,
  deleteCodespace,
  listCodespaces,
  getCodespacePortUrl,
  type CodespaceInfo
} from './gh-cli.js';
import { execInCodespace, waitForPortListening } from './ssh.js';
import {
  installClaudeCode,
  installSudocodeGlobally,
  installSudocodeFromLocal,
  initializeSudocodeProject,
  startSudocodeServer
} from './setup.js';

/**
 * GitHub Codespaces provider implementation
 */
export class CodespacesProvider implements Provider {
  readonly type = 'codespaces' as const;

  constructor(private config: CodespacesConfig) {}

  /**
   * Deploy a new Codespace with sudocode
   */
  async deploy(options: DeployOptions): Promise<Deployment> {
    // Validate prerequisites
    await this.checkPrerequisites();

    // Extract codespace-specific options
    const csOptions = options.providerOptions as any;
    const machine = csOptions.machine || 'basicLinux32gb';
    const retentionPeriod = csOptions.retentionPeriod || 14;

    // Determine workspace directory
    const workspaceName = options.repository.split('/')[1];
    const workspaceDir = options.workspaceDir || `/workspaces/${workspaceName}`;

    try {
      // Create Codespace with hardcoded 5-minute idle timeout
      // Our idle timeout daemon will prevent GitHub's auto-stop until user's idle_timeout expires
      const codespace = await createCodespace({
        repository: options.repository,
        machine,
        idleTimeout: 5, // Hardcoded 5 minutes - daemon prevents auto-stop
        retentionPeriod,
        branch: options.branch
      });

      // Wait for ready
      await waitForCodespaceReady(codespace.name, 30);

      // Install sudocode
      const isDev = options.sudocode.mode === 'local';
      await this.installSudocode(codespace.name, isDev, workspaceDir);

      // Start server
      const port = options.server.port || 3000;
      const keepAliveHours = options.server.keepAliveHours || 72;

      await this.startServer(
        codespace.name,
        port,
        keepAliveHours,
        workspaceDir,
        isDev
      );

      // Get URLs
      const urls = await this.getUrls(codespace.name, port);

      // Return deployment info
      return {
        id: codespace.name,
        name: codespace.name,
        provider: 'codespaces',
        repository: options.repository,
        branch: options.branch,
        status: 'running',
        createdAt: new Date().toISOString(),
        urls,
        keepAliveHours,
        idleTimeout: options.server.idleTimeout,
        metadata: {
          codespaces: {
            machine,
            retentionPeriod
          }
        }
      };

    } catch (error: any) {
      throw new DeploymentFailedError(error.message, error);
    }
  }

  /**
   * Stop and delete a Codespace
   */
  async stop(name: string): Promise<void> {
    try {
      await deleteCodespace(name);
    } catch (error: any) {
      throw new ProviderError('codespaces', 'stop', error.message);
    }
  }

  /**
   * Get status of a Codespace
   */
  async getStatus(name: string): Promise<DeploymentStatus> {
    try {
      const codespaces = await listCodespaces();
      const cs = codespaces.find(c => c.name === name);

      if (!cs) {
        throw new ProviderError('codespaces', 'getStatus', `Codespace ${name} not found`);
      }

      return this.mapCodespaceState(cs.state);
    } catch (error: any) {
      throw new ProviderError('codespaces', 'getStatus', error.message);
    }
  }

  /**
   * List Codespaces
   */
  async list(filters?: ListFilters): Promise<Deployment[]> {
    try {
      const codespaces = await listCodespaces();

      // Convert to Deployment objects
      let deployments = codespaces.map(cs => this.codespaceToDeployment(cs));

      // Apply filters
      if (filters?.status) {
        deployments = deployments.filter(d => 
          filters.status!.includes(d.status)
        );
      }
      if (filters?.repository) {
        deployments = deployments.filter(d => 
          d.repository === filters.repository
        );
      }
      if (filters?.createdAfter) {
        deployments = deployments.filter(d => 
          d.createdAt >= filters.createdAfter!
        );
      }
      if (filters?.createdBefore) {
        deployments = deployments.filter(d => 
          d.createdAt <= filters.createdBefore!
        );
      }

      return deployments;
    } catch (error: any) {
      throw new ProviderError('codespaces', 'list', error.message);
    }
  }

  /**
   * Get URLs for a Codespace
   */
  async getUrls(name: string, port: number = 3000): Promise<DeploymentUrls> {
    const workspace = `https://${name}.github.dev`;
    const sudocode = await getCodespacePortUrl(name, port);

    return {
      workspace,
      sudocode,
      ssh: `gh codespace ssh --codespace ${name}`
    };
  }

  /**
   * Check prerequisites (gh CLI installed and authenticated)
   */
  private async checkPrerequisites(): Promise<void> {
    try {
      await checkGhCliInstalled();
    } catch {
      throw new AuthenticationError(
        'codespaces',
        'GitHub CLI not found. Install from https://cli.github.com'
      );
    }

    try {
      await checkGhAuthenticated();
    } catch {
      throw new AuthenticationError(
        'codespaces',
        'Not authenticated with GitHub. Run: gh auth login'
      );
    }
  }

  /**
   * Install sudocode in Codespace
   */
  private async installSudocode(
    name: string,
    isDev: boolean,
    workspaceDir: string
  ): Promise<void> {
    await installClaudeCode(name, workspaceDir);

    if (isDev) {
      await installSudocodeFromLocal(name, workspaceDir);
    } else {
      await installSudocodeGlobally(name, workspaceDir);
    }

    await initializeSudocodeProject(name, workspaceDir);
  }

  /**
   * Start sudocode server
   */
  private async startServer(
    name: string,
    port: number,
    keepAliveHours: number,
    workspaceDir: string,
    isDev: boolean
  ): Promise<void> {
    // Start server process
    await startSudocodeServer(name, port, keepAliveHours, workspaceDir, isDev);

    // Wait for port to be listening
    await waitForPortListening(name, port, 30);

    // Register port with GitHub (handles local port conflicts)
    await this.registerPortWithGitHub(name, port);
  }

  /**
   * Register port with GitHub forwarding system
   */
  private async registerPortWithGitHub(name: string, port: number): Promise<void> {
    // Port registration logic from original implementation
    // (simplified for spec - actual implementation will match original)
    const { exec } = await import('child_process');

    const forwardProcess = exec(
      `gh codespace ports forward ${port}:${port} --codespace ${name}`
    );

    await new Promise(resolve => setTimeout(resolve, 2000));

    if (forwardProcess.pid) {
      try {
        process.kill(forwardProcess.pid);
      } catch {
        // Ignore
      }
    }
  }

  /**
   * Map GitHub Codespace state to DeploymentStatus
   */
  private mapCodespaceState(state: string): DeploymentStatus {
    switch (state) {
      case 'Available':
        return 'running';
      case 'Starting':
      case 'Created':
        return 'starting';
      case 'Stopping':
        return 'stopping';
      case 'Stopped':
      case 'Shutdown':
        return 'stopped';
      case 'Failed':
        return 'failed';
      default:
        return 'provisioning';
    }
  }

  /**
   * Convert CodespaceInfo to Deployment
   */
  private codespaceToDeployment(cs: CodespaceInfo): Deployment {
    return {
      id: cs.name,
      name: cs.name,
      provider: 'codespaces',
      repository: cs.repository || 'unknown',
      status: this.mapCodespaceState(cs.state),
      createdAt: cs.createdAt || new Date().toISOString(),
      urls: {
        workspace: cs.url,
        sudocode: `https://${cs.name}-3000.app.github.dev`,
        ssh: `gh codespace ssh --codespace ${cs.name}`
      },
      keepAliveHours: 72, // Default
      metadata: {
        codespaces: {
          machine: 'basicLinux32gb',
          retentionPeriod: 14
        }
      }
    };
  }
}
