import { exec } from 'child_process';

/**
 * Execute a command in the codespace via SSH using login shell
 * 
 * Uses `bash -l -c` to ensure:
 * - Commands run from default workspace directory (/workspaces/<repo>)
 * - Environment variables are properly set
 * - Installed tools are in PATH
 * 
 * The cwd option can override the default directory when needed.
 */
export async function execInCodespace(
  name: string,
  command: string,
  options: ExecOptions = {}
): Promise<string> {
  const {
    timeout = 120000,
    cwd,
    streamOutput = true
  } = options;

  // If cwd is specified, wrap command to cd first
  const wrappedCommand = cwd
    ? `cd ${cwd} && ${command}`
    : command;

  // Escape command for shell execution (handle single quotes)
  const escapedCommand = wrappedCommand.replace(/'/g, "'\\''");

  // Use login shell pattern for proper environment setup
  const sshCommand = `gh codespace ssh --codespace ${name} -- "bash -l -c '${escapedCommand}'"`;

  return new Promise((resolve, reject) => {
    const child = exec(sshCommand, { timeout }, (error, stdout, stderr) => {
      if (error) {
        reject(new Error(
          `Failed to execute in codespace ${name}: ${command}\n${error.message}\n${stderr}`
        ));
      } else {
        resolve(stdout);
      }
    });

    if (streamOutput && child.stdout && child.stderr) {
      child.stdout.on('data', (data) => process.stdout.write(data));
      child.stderr.on('data', (data) => process.stderr.write(data));
    }
  });
}
```

